 static MonitorConfig Draft(Window w){return (MonitorConfig)Get(w,"taskbarDraft");}
 static void Mode(Window w,string name){var chip=Named<System.Windows.Controls.Primitives.ToggleButton>(w,"文字配色模式-"+name);chip.IsChecked=true;chip.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);Window pet=null;var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};try{
 var a=new TaskbarAppearance{PerItemColors=true,AutoTheme=false,AutoContrastText=true,Opacity=.68,Transparent=false};a.EnsureItems();a.Item("cpu").LabelRamp=UsageRamp.Between("#FF0000","#FF0000");Check(a.TextRamp(a.Item("cpu"),true).At(0).ToArgb()!=D.Color.Red.ToArgb(),"high contrast overrides retained custom item palette");a.AutoContrastText=false;a.AutoTheme=true;Check(a.TextRamp(a.Item("cpu"),true).At(0).ToArgb()!=D.Color.Red.ToArgb(),"system mode overrides retained custom item palette");a.AutoTheme=false;Check(a.TextRamp(a.Item("cpu"),true).At(0).ToArgb()==D.Color.Red.ToArgb(),"custom mode restores retained colors");
 var cfg=new MonitorConfig{Appearance=a,TaskbarItems=new List<string>{"cpu"}};var sample=new SystemSample{Cpu=50};using(var b=TaskbarPainter.Preview(cfg,sample,100)){Check(b.GetPixel(0,0).A>=170&&b.GetPixel(0,0).A<=175,"legacy opacity migrates to background alpha only");}a.Graphs=true;a.Item("cpu").UsageRamp=UsageRamp.Between("#00FF00","#00FF00");using(var b=TaskbarPainter.Preview(cfg,sample,100)){Check(Enumerable.Range(0,b.Width).Any(x=>Enumerable.Range(0,b.Height).Any(y=>{var c=b.GetPixel(x,y);return c.A==255&&c.G>240&&c.R<10;})),"bar stays opaque over translucent background");}
 a.Graphs=false;a.FontSize=18;a.LatinFontSize=18;using(var b=TaskbarPainter.Preview(cfg,sample,100)){Check(Enumerable.Range(0,b.Width).Any(x=>Enumerable.Range(0,b.Height).Any(y=>{var c=b.GetPixel(x,y);return c.A==255&&c.R>245&&c.G<10;})),"custom text keeps opaque color over translucent background");}
 using(var view=new TaskbarMonitor()){view.Config=cfg;var geometry=TaskbarPainter.Geometry(cfg,1,100,sample);view.ClientSize=geometry.Size;view.Location=new D.Point(100,100);using(var canvas=TaskbarPainter.Surface(cfg,sample,geometry,geometry.Size)){Check(view.PresentLayered(canvas)&&view.LastLayeredError==0,"native per-pixel surface uploads successfully");view.Show();Pump();Check(view.LastLayeredError==0&&view.Opacity==1&&view.TransparencyKey.IsEmpty,"native show preserves per-pixel alpha without global fade");int before=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);for(int i=0;i<100;i++)if(!view.PresentLayered(canvas))throw new Exception("Repeated layered upload failed");int after=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);Check(after-before<5,"repeated native uploads release GDI resources");view.Hide();}}
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;assistant.Config.Monitor.Appearance=a;assistant.Save();pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("任务栏外观");Click(w,"配色与文字");
 Mode(w,"自动高对比");Check(new[]{"自定义配色","自动高对比","跟随系统"}.Count(n=>Named<System.Windows.Controls.Primitives.ToggleButton>(w,"文字配色模式-"+n).IsChecked==true)==1,"exactly one text mode is selected");Check(Draft(w).Appearance.AutoContrastText&&!Draft(w).Appearance.AutoTheme,"high contrast selects exclusive mode");Check(!Tree(w).OfType<UsageRampEditor>().Any(e=>e.IsVisible),"automatic text mode hides manual palette editor");Check(Tree(w).OfType<TextBox>().Any(e=>System.Windows.Automation.AutomationProperties.GetName(e)=="中文字体名称"&&e.IsVisible),"automatic mode keeps font editor available");Named<ComboBox>(w,"配色对象").SelectedIndex=2;Pump();Check(Tree(w).OfType<UsageRampEditor>().Any(e=>e.IsVisible),"high contrast mode still allows independent bar coloring");Named<ComboBox>(w,"配色对象").SelectedIndex=0;Mode(w,"跟随系统");Check(!Draft(w).Appearance.AutoContrastText&&Draft(w).Appearance.AutoTheme,"system selects exclusive mode");Mode(w,"自定义配色");Check(!Draft(w).Appearance.AutoContrastText&&!Draft(w).Appearance.AutoTheme,"custom selects exclusive mode");Check(Tree(w).OfType<UsageRampEditor>().Any(e=>e.IsVisible),"custom mode restores palette editor");
 Named<ComboBox>(w,"配色对象").SelectedIndex=3;var opacity=Named<TextBox>(w,"背景不透明度（0–100%）");opacity.Text="35";Check(Math.Abs((double)typeof(TaskbarAppearance).GetProperty("EffectiveBackgroundOpacity").GetValue(Draft(w).Appearance,null)-.35)<.001,"background slider updates independent draft alpha");Shot(w,Path.Combine(args[0],"background.png"));Named<ComboBox>(w,"配色对象").SelectedIndex=0;Mode(w,"自动高对比");Shot(w,Path.Combine(args[0],"contrast-a.png"));w.SetTheme("b",false);Shot(w,Path.Combine(args[0],"contrast-b.png"));w.SetTheme("a",false);Mode(w,"自定义配色");Shot(w,Path.Combine(args[0],"custom.png"));Click(w,"应用并保存任务栏外观");var json=new JavaScriptSerializer();var saved=json.Serialize(assistant.Config.Monitor.Appearance);var runtime=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(json.Serialize(runtime.Config.Monitor.Appearance)==saved,"color mode and background opacity survive runtime reload");runtime.Telemetry.Dispose();
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"color-modes-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_settings=true}));return failures==0?0:1;}
